// Where the country's immigrants come from (left) and where its emigrants
// live (right), at the estimate in force on the map clock. One query frame,
// one row per corridor: side ('in' or 'out'), code (the partner's M49 code),
// name, people, share (of that side's total).
//
// A country can be both an origin and a destination, so each partner is a node
// per side: 'in:<code>' and 'out:<code>'; the country itself is 'country'. A
// click on a partner selects it, as a click on the map does. Only partners
// with 2% of their side are labelled, by short name; the tooltip names all.
const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const IN = '#12939A';
const OUT = '#F08A24';
const LABELLED = 2;

const frame = context.panel.data.series[0];
const column = (name) => Array.from(frame?.fields.find((f) => f.name === name)?.values ?? []);
const side = column('side');
const code = column('code');
const name = column('name');
const people = column('people');
const share = column('share');

const country = context.grafana.replaceVariables('${country:text}');
const labels = { country };
const shortLabels = { country };
const codes = {};
const nodes = [{ name: 'country', itemStyle: { color: theme.colors.text.secondary }, label: { show: true, position: 'top' } }];
const links = [];
side.forEach((s, i) => {
  const id = `${s}:${code[i]}`;
  labels[id] = name[i];
  shortLabels[id] = String(name[i]).replace(/\s*\(.*\)$/, '');
  codes[id] = String(code[i]);
  nodes.push({
    name: id,
    itemStyle: { color: s === 'in' ? IN : OUT },
    label: { show: Number(share[i]) >= LABELLED, position: s === 'in' ? 'left' : 'right' },
  });
  links.push({
    source: s === 'in' ? id : 'country',
    target: s === 'in' ? 'country' : id,
    value: Number(people[i]),
    share: Number(share[i]),
    lineStyle: { color: s === 'in' ? IN : OUT },
  });
});

const count = (v) => (v >= 999500 ? `${(v / 1e6).toFixed(1)}M` : v >= 1e3 ? `${Math.round(v / 1e3)}k` : String(Math.round(v)));

chart.off('click');
chart.on('click', (params) => {
  if (params.dataType === 'node' && codes[params.name]) {
    location.partial({ 'var-country': codes[params.name] });
  }
});

if (links.length === 0) {
  return {
    title: {
      text: `No corridor for ${country}`,
      left: 'center',
      top: 'middle',
      textStyle: { color: theme.colors.text.secondary, fontSize: 14, fontWeight: 'normal' },
    },
    series: [],
  };
}

return {
  tooltip: {
    trigger: 'item',
    formatter: (params) => {
      if (params.dataType !== 'edge') {
        return labels[params.name];
      }
      const { source, target, value, share } = params.data;
      return `${labels[source]} → ${labels[target]}<br/><b>${count(value)}</b> · ${share}% of all ${source === 'country' ? 'emigrants' : 'immigrants'}`;
    },
  },
  series: [
    {
      type: 'sankey',
      left: '24%',
      right: '24%',
      top: 24,
      bottom: 8,
      nodeWidth: 10,
      nodeGap: 6,
      nodeAlign: 'justify',
      // Keep the query's order: largest corridor on top.
      layoutIterations: 0,
      draggable: false,
      emphasis: { focus: 'adjacency' },
      data: nodes,
      links,
      lineStyle: { opacity: 0.35, curveness: 0.5 },
      label: {
        color: theme.colors.text.primary,
        fontSize: 11,
        overflow: 'truncate',
        // The margin either side, less a gap.
        width: Math.max(48, (chart.getWidth?.() ?? 400) * 0.24 - 12),
        formatter: (params) => shortLabels[params.name],
      },
    },
  ],
};

// Men (left) and women (right) in the country's largest corridors, largest on
// top, each labelled with its share of women and named without its
// parenthetical (the tooltip names it in full). One query frame: Country, code
// (the partner's M49 code), Men, Women. A click on a bar selects that country,
// as a click on the map does.
const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const MEN = '#5794F2';
const WOMEN = '#FF9830';

const frame = context.panel.data.series[0];
const column = (name) => Array.from(frame?.fields.find((f) => f.name === name)?.values ?? []);
const country = column('Country');
const code = column('code');
const men = column('Men').map(Number);
const women = column('Women').map(Number);
const womenShare = (i) => (100 * women[i]) / (men[i] + women[i]);

const count = (v) => (v >= 999500 ? `${(v / 1e6).toFixed(1)}M` : v >= 1e3 ? `${Math.round(v / 1e3)}k` : String(Math.round(v)));

chart.off('click');
chart.on('click', (params) => {
  if (params.componentType === 'series' && code[params.dataIndex] !== undefined) {
    location.partial({ 'var-country': String(code[params.dataIndex]) });
  }
});

return {
  legend: { top: 0, textStyle: { color: theme.colors.text.secondary } },
  grid: { left: 8, right: 48, top: 28, bottom: 8, containLabel: true },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    formatter: ([{ dataIndex: i }]) =>
      `${country[i]}<br/>Men <b>${count(men[i])}</b> · Women <b>${count(women[i])}</b> (${womenShare(i).toFixed(1)}%)`,
  },
  xAxis: {
    type: 'value',
    axisLabel: { color: theme.colors.text.secondary, formatter: (v) => count(Math.abs(v)) },
    splitLine: { lineStyle: { opacity: 0.15 } },
  },
  yAxis: {
    type: 'category',
    data: country.map((c) => String(c).replace(/\s*\(.*\)$/, '')),
    inverse: true,
    axisTick: { show: false },
    axisLabel: { color: theme.colors.text.primary, width: 110, overflow: 'truncate' },
  },
  series: [
    { name: 'Men', type: 'bar', stack: 'sex', data: men.map((v) => -v), itemStyle: { color: MEN }, barCategoryGap: '25%' },
    {
      name: 'Women',
      type: 'bar',
      stack: 'sex',
      data: women,
      itemStyle: { color: WOMEN },
      label: {
        show: true,
        position: 'right',
        color: theme.colors.text.secondary,
        fontSize: 10,
        formatter: (params) => `${womenShare(params.dataIndex).toFixed(0)}%`,
      },
    },
  ],
};
